INSERT INTO pdf_insights (id, slug, language, title, subtitle, short_title, content_type, status, author, publication_date, data_period, page_count, reading_time, executive_thesis, short_summary, executive_summary, key_findings, leadership_implications, strategic_questions, methodology, limitations, regions, topics, expertise, keywords, gating_model, pdf_key, original_filename, checksum, mime_type, file_size, version, extraction_confidence, created_by, updated_by, created_at, updated_at) VALUES ('58a4abcd-58a6-47c5-8b60-dd239408e0e0', 'cbam-august-guidance-turkish-exporters-58a4abcd', 'en', 'The August guidance: what the Commission’s new CBAM rulebook asks of Turkish exporters in the first paying year', 'Ten guidance documents published on 14 August 2026, and verifier guidance on 24 August, set out how emissions data for 2026 imports should be monitored, calculated and verified.', 'The August guidance', 'Strategic Perspective', 'review_required', 'Ahmed Furkan Gul', '2026-10-25', 'October 2026', 6, 18, 'Ten guidance documents published on 14 August 2026, and verifier guidance on 24 August, set out how emissions data for 2026 imports should be monitored, calculated and verified.', 'On 14 August 2026 the European Commission published ten guidance documents for the definitive period of the Carbon Border Adjustment Mechanism (CBAM, known in Türkiye as SKDM). They are written mainly for operators of installations outside the EU, which includes Turkish steel, aluminium, cement and fertiliser plants. On 24 August it followed with guidance for verifiers and accreditation bodies.', 'On 14 August 2026 the European Commission published ten guidance documents for the definitive period of the Carbon Border Adjustment Mechanism (CBAM, known in Türkiye as SKDM). They are written mainly for operators of installations outside the EU, which includes Turkish steel, aluminium, cement and fertiliser plants. On 24 August it followed with guidance for verifiers and accreditation bodies. 2026 is the first year in which imports carry a CBAM cost, but the money moves in 2027. EU importers buy certificates from 1 February 2027 and declare and surrender them for 2026 imports by 30 September 2027. Verifiers begin issuing verification reports in the CBAM Registry in January 2027. Emissions data for this year’s shipments therefore has to be monitored now and verified early next year. The sound question for a Turkish exporter is not whether CBAM applies to us, but whether our 2026 emissions data will be calculated by the method in the guidance and ready for a verifier in time for our buyers’ first declaration.', '[{"title": "Ten guides and a verifier rulebook", "explanation": "On 14 August 2026 the European Commission published ten guidance documents for the definitive period of the Carbon Border Adjustment Mechanism (CBAM, known in Türkiye as SKDM). They are written mainly for operators of installations outside the EU, which includes Turkish steel, aluminium, cement and fertiliser plants. On 24 August it followed with guidance for verifiers and accreditation bodies.", "page": 2}, {"title": "The cost attaches to 2026 imports", "explanation": "2026 is the first year in which imports carry a CBAM cost, but the money moves in 2027. EU importers buy certificates from 1 February 2027 and declare and surrender them for 2026 imports by 30 September 2027. Verifiers begin issuing verification reports in the CBAM Registry in January 2027. Emissions data for this year’s shipments therefore has to be monitored now and verified early next year.", "page": 2}, {"title": "Verified actual values decide the bill", "explanation": "The sound question for a Turkish exporter is not whether CBAM applies to us, but whether our 2026 emissions data will be calculated by the method in the guidance and ready for a verifier in time for our buyers’ first declaration.", "page": 2}]', '[]', '["Which of our products sold into the EU fall under CBAM, and which sector guide applies to each of them?", "Do we have a monitoring plan that follows Guidance No. 3 and the sector guide for our production route?", "Can we calculate embedded emissions for 2026 shipments installation by installation, including precursors bought from other plants?", "Which EU buyers will use our actual values, and which are planning to use default values?", "Have we chosen an accredited verifier, and when can they visit and report?", "Who in the company sends the emissions communication to each buyer, and in what format?", "Have we compared actual and default values, including the yearly mark-up, for our main products?", "Do any of our buyers expect a reduction for carbon prices paid in Türkiye, and what have we promised them?"]', 'Desk review of official EU sources checked on 25 October 2026, combined with Ganrich Advisory’s October 2026 review of opportunities in Türkiye.', 'General information, not legal, customs, tax or engineering advice. Rules and dates change; confirm against official sources. No client work or results are described.', '["Türkiye", "European Union"]', '["CBAM", "Carbon emissions", "EU market access"]', '["Operating model"]', '["CBAM", "SKDM", "CBAM guidance", "verification", "default values", "embedded emissions"]', 'fully_ungated', 'pdf-insights/58a4abcd-58a6-47c5-8b60-dd239408e0e0/v1/Ganrich-CBAM-August-Guidance-EN.pdf', 'Ganrich-CBAM-August-Guidance-EN.pdf', '7e8554bc63b07ecaa546bbb209255e3b0184a8d8452963f5838275cd402f873e', 'application/pdf', 268035, 1, 'reviewed', 'furkangul@ganrichadvisory.com', 'furkangul@ganrichadvisory.com', '2026-10-25T18:50:00.000Z', '2026-10-25T18:50:00.000Z');
INSERT INTO pdf_insight_versions (id, insight_id, version, r2_key, filename, checksum, file_size, uploaded_by, uploaded_at, status) VALUES ('1b7f0d0e-1a40-4c55-9c71-000000000027', '58a4abcd-58a6-47c5-8b60-dd239408e0e0', 1, 'pdf-insights/58a4abcd-58a6-47c5-8b60-dd239408e0e0/v1/Ganrich-CBAM-August-Guidance-EN.pdf', 'Ganrich-CBAM-August-Guidance-EN.pdf', '7e8554bc63b07ecaa546bbb209255e3b0184a8d8452963f5838275cd402f873e', 268035, 'furkangul@ganrichadvisory.com', '2026-10-25T18:50:00.000Z', 'current');
INSERT INTO pdf_insights (id, slug, language, title, subtitle, short_title, content_type, status, author, publication_date, data_period, page_count, reading_time, executive_thesis, short_summary, executive_summary, key_findings, leadership_implications, strategic_questions, methodology, limitations, regions, topics, expertise, keywords, gating_model, pdf_key, original_filename, checksum, mime_type, file_size, version, extraction_confidence, created_by, updated_by, created_at, updated_at) VALUES ('1d698fcc-8f2a-4d1c-b07a-9bff252aa405', 'skdm-agustos-rehberleri-turk-ihracatci-1d698fcc', 'tr', 'Ağustos rehberleri: SKDM (CBAM) ilk maliyet yılında Türk ihracatçıdan ne istiyor?', 'Avrupa Komisyonu’nun 14 Ağustos 2026’da yayımladığı on rehber ve 24 Ağustos’taki doğrulayıcı rehberi, 2026 ithalatına ait emisyon verisinin nasıl izleneceğini, hesaplanacağını ve doğrulanacağını anlatıyor.', 'Ağustos rehberleri', 'Strategic Perspective', 'review_required', 'Ahmed Furkan Gül', '2026-10-25', 'Ekim 2026', 6, 18, 'Avrupa Komisyonu’nun 14 Ağustos 2026’da yayımladığı on rehber ve 24 Ağustos’taki doğrulayıcı rehberi, 2026 ithalatına ait emisyon verisinin nasıl izleneceğini, hesaplanacağını ve doğrulanacağını anlatıyor.', 'Avrupa Komisyonu 14 Ağustos 2026’da Sınırda Karbon Düzenleme Mekanizması’nın (SKDM, AB’deki adıyla CBAM) kesin dönemi için on rehber yayımladı. Rehberler esas olarak AB dışındaki tesis işletmecilerine yazıldı; Türk demir-çelik, alüminyum, çimento ve gübre tesisleri de bu kapsamda. Komisyon 24 Ağustos’ta doğrulayıcılar ve akreditasyon kuruluşları için ayrı bir rehber yayımladı.', 'Avrupa Komisyonu 14 Ağustos 2026’da Sınırda Karbon Düzenleme Mekanizması’nın (SKDM, AB’deki adıyla CBAM) kesin dönemi için on rehber yayımladı. Rehberler esas olarak AB dışındaki tesis işletmecilerine yazıldı; Türk demir-çelik, alüminyum, çimento ve gübre tesisleri de bu kapsamda. Komisyon 24 Ağustos’ta doğrulayıcılar ve akreditasyon kuruluşları için ayrı bir rehber yayımladı. 2026, ithalatın SKDM maliyeti taşıdığı ilk yıl; ancak ödeme 2027’de yapılıyor. AB ithalatçıları sertifikaları 1 Şubat 2027’den itibaren satın alıyor, 2026 ithalatı için beyanı ve sertifika teslimini 30 Eylül 2027’ye kadar yapıyor. Doğrulayıcılar SKDM Kayıt Sistemi’nde doğrulama raporlarını Ocak 2027’den itibaren düzenlemeye başlıyor. Bu yılki sevkiyatların emisyon verisi bugünden izlenmeli ve gelecek yılın başında doğrulanmaya hazır olmalı. Türk ihracatçı için doğru soru “SKDM bizi kapsıyor mu?” değil; “2026 emisyon verimiz rehberdeki yönteme göre hesaplanmış ve alıcımızın ilk beyanına yetişecek şekilde doğrulayıcıya hazır olacak mı?” sorusudur.', '[{"title": "On rehber ve doğrulayıcı kuralları", "explanation": "Avrupa Komisyonu 14 Ağustos 2026’da Sınırda Karbon Düzenleme Mekanizması’nın (SKDM, AB’deki adıyla CBAM) kesin dönemi için on rehber yayımladı. Rehberler esas olarak AB dışındaki tesis işletmecilerine yazıldı; Türk demir-çelik, alüminyum, çimento ve gübre tesisleri de bu kapsamda. Komisyon 24 Ağustos’ta doğrulayıcılar ve akreditasyon kuruluşları için ayrı bir rehber yayımladı.", "page": 2}, {"title": "Maliyet 2026 ithalatına bağlanıyor", "explanation": "2026, ithalatın SKDM maliyeti taşıdığı ilk yıl; ancak ödeme 2027’de yapılıyor. AB ithalatçıları sertifikaları 1 Şubat 2027’den itibaren satın alıyor, 2026 ithalatı için beyanı ve sertifika teslimini 30 Eylül 2027’ye kadar yapıyor. Doğrulayıcılar SKDM Kayıt Sistemi’nde doğrulama raporlarını Ocak 2027’den itibaren düzenlemeye başlıyor. Bu yılki sevkiyatların emisyon verisi bugünden izlenmeli ve gelecek yılın başında doğrulanmaya hazır olmalı.", "page": 2}, {"title": "Faturayı doğrulanmış gerçek değer belirliyor", "explanation": "Türk ihracatçı için doğru soru “SKDM bizi kapsıyor mu?” değil; “2026 emisyon verimiz rehberdeki yönteme göre hesaplanmış ve alıcımızın ilk beyanına yetişecek şekilde doğrulayıcıya hazır olacak mı?” sorusudur.", "page": 2}]', '[]', '["AB’ye sattığımız ürünlerden hangileri SKDM kapsamında ve her biri için hangi sektör rehberi geçerli?", "3 No’lu rehbere ve üretim yolumuzun sektör rehberine uygun bir izleme planımız var mı?", "2026 sevkiyatları için gömülü emisyonu, başka tesislerden aldığımız öncül maddeler dahil, tesis bazında hesaplayabiliyor muyuz?", "Hangi AB alıcılarımız gerçek değerlerimizi kullanacak, hangileri varsayılan değer kullanmayı planlıyor?", "Akredite bir doğrulayıcı seçtik mi; ne zaman ziyaret edip rapor verebilir?", "Her alıcıya emisyon bildirimini şirkette kim, hangi formatta gönderiyor?", "Ana ürünlerimiz için gerçek ve varsayılan değerleri, yıllık ek pay dahil karşılaştırdık mı?", "Alıcılarımızdan biri Türkiye’de ödenen karbon fiyatı için indirim bekliyor mu ve onlara ne söz verdik?"]', '25 Ekim 2026’da kontrol edilen resmî AB kaynaklarının masa başı incelemesi ile Ganrich Advisory’nin Ekim 2026 Türkiye fırsat incelemesinin birleşimi.', 'Genel bilgi niteliğindedir; hukuki, gümrük, vergi veya mühendislik danışmanlığı değildir. Kurallar ve tarihler değişebilir; resmî kaynaklardan teyit edin. Müşteri çalışması veya sonucu anlatılmaz.', '["Türkiye", "European Union"]', '["CBAM", "Carbon emissions", "EU market access"]', '["Operating model"]', '["CBAM", "SKDM", "CBAM guidance", "verification", "default values", "embedded emissions"]', 'fully_ungated', 'pdf-insights/1d698fcc-8f2a-4d1c-b07a-9bff252aa405/v1/Ganrich-SKDM-Agustos-Rehberleri-TR.pdf', 'Ganrich-SKDM-Agustos-Rehberleri-TR.pdf', 'c1abdd7c5fb6da74a50a0da21736ba717174c0b207054b080a072953bd770733', 'application/pdf', 281052, 1, 'reviewed', 'furkangul@ganrichadvisory.com', 'furkangul@ganrichadvisory.com', '2026-10-25T18:50:00.000Z', '2026-10-25T18:50:00.000Z');
